import base64
import json
import requests

class FireblocksAPI:
    def __init__(self, public_key, secret_key, environment='prod'):
        self.public_key = public_key
        self.secret_key = secret_key
        self.environment = environment
        self.api_url = self.get_api_url()

    def get_api_url(self):
        if self.environment == 'prod':
            return 'https://api.fireblocks.io'
        elif self.environment =='stg':
            return 'https://api.staging.fireblocks.io'
        else:
            raise ValueError('Invalid environment')

    def get_headers(self):
        return {
            'Content-Type': 'application/json',
            'X-FBX-PUBLIC-KEY': self.public_key,
            'X-FBX-SIGNATURE': self.sign_request()
        }

    def sign_request(self):
        timestamp = str(int(time.time()))
        message = json.dumps({'timestamp': timestamp,'method': 'GET', 'path': '/v1/network'}).encode('utf-8')
        signature = base64.b64encode(hmac.new(self.secret_key.encode('utf-8'), message, hashlib.sha256).digest())
        return signature.decode('utf-8')

    def get_network_info(self):
        response = requests.get(self.api_url + '/v1/network', headers=self.get_headers())
        return response.json()

    def get_account_info(self, account_id):
        response = requests.get(self.api_url + f'/v1/accounts/{account_id}', headers=self.get_headers())
        return response.json()

    def create_account(self, name, balance):
        data = {'name': name, 'balance': balance}
        response = requests.post(self.api_url + '/v1/accounts', headers=self.get_headers(), data=json.dumps(data))
        return response.json()

    def get_block_info(self, block_id):
        response = requests.get(self.api_url + f'/v1/blocks/{block_id}', headers=self.get_headers())
        return response.json()

    def create_block(self, name, description):
        data = {'name': name, 'description': description}
        response = requests.post(self.api_url + '/v1/blocks', headers=self.get_headers(), data=json.dumps(data))
        return response.json()

    def get_transaction_info(self, transaction_id):
        response = requests.get(self.api_url + f'/v1/transactions/{transaction_id}', headers=self.get_headers())
        return response.json()

    def create_transaction(self, account_id, block_id, amount, currency):
        data = {'account_id': account_id, 'block_id': block_id, 'amount': amount, 'currency': currency}
        response = requests.post(self.api_url + '/v1/transactions', headers=self.get_headers(), data=json.dumps(data))
        return response.json()

