function init_clean_book() {
    // Get the project name and author from the configuration
    var project = "{project}";
    var author = "{author}";

    // Get the project description from the configuration
    var description = "{description}";

    // Update the page title and meta tags
    document.title = project;
    document.querySelector('meta[name="description"]').content = description;

    // Update the page header and navigation
    document.querySelector('h1').textContent = project;
    document.querySelector('nav ul').innerHTML = toc;

    // Update the page main section and body
    document.querySelector('main section').innerHTML = body;

    // Update the page footer and copyright
    document.querySelector('footer').textContent = "&copy; " + year + " " + author;

    // Initialize the responsive layout
    init_responsive_layout();
}

function init_responsive_layout() {
    // Get the window width and height
    var width = window.innerWidth || document.documentElement.clientWidth;
    var height = window.innerHeight || document.documentElement.clientHeight;

    // Update the page layout based on the window size
    if (width < 768) {
        // Mobile layout
        document.querySelector('header').classList.add('mobile');
        document.querySelector('nav').classList.add('mobile');
        document.querySelector('main').classList.add('mobile');
        document.querySelector('footer').classList.add('mobile');
    } else if (width < 992) {
        // Tablet layout
        document.querySelector('header').classList.add('tablet');
        document.querySelector('nav').classList.add('tablet');
        document.querySelector('main').classList.add('tablet');
        document.querySelector('footer').classList.add('tablet');
    } else {
        // Desktop layout
        document.querySelector('header').classList.add('desktop');
        document.querySelector('nav').classList.add('desktop');
        document.querySelector('main').classList.add('desktop');
        document.querySelector('footer').classList.add('desktop');
    }

    // Update the page layout when the window size changes
    window.addEventListener('resize', function() {
        init_responsive_layout();
    });
}

